#nullable enable // autogenerated

using System.ComponentModel;
using Newtonsoft.Json;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackTextures
    {
        public ResourcePackTexture[]? textures;
    }
    public class ResourcePackTexture
    {
        public string? texture;
        public string? key;
        [DefaultValue(1)]
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int filter = 1;
        public ResourcePackSprite[]? slices;
    }
    public class ResourcePackSprite
    {
        [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
        public string? key;
        [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
        public string[]? tags;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public bool single;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int x;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int y;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int width;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int height;
        [DefaultValue(0.5f)]
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public float pivotX = 0.5f;
        [DefaultValue(0.5f)]
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public float pivotY = 0.5f;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderLeft;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderBottom;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderRight;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public int borderTop;
        [JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
        public bool fullRect;
    }
}
